function ApiPage({onNavigate}){
  return(<div className="page">
    <div className="info-hero"><div className="section-label">API</div><h1>Build on CastSlate</h1><p>Integrate our talent search and casting pipeline directly into your production tools.</p></div>
    <div style={{maxWidth:800,margin:"0 auto"}}>
      <div className="card mb-32"><h3 style={{fontSize:18,fontWeight:700,marginBottom:16}}>REST API Endpoints</h3>
        <div className="api-code">{`GET    /api/v1/castings          # List active castings
POST   /api/v1/castings          # Create new casting
GET    /api/v1/castings/:id      # Get casting details
GET    /api/v1/submissions/:id   # Get submissions for casting
POST   /api/v1/submissions       # Submit talent to casting
GET    /api/v1/talent/search     # Search talent directory
GET    /api/v1/talent/:id        # Get talent profile
POST   /api/v1/callbacks         # Add talent to callbacks`}</div></div>
      <div className="grid-2 mb-32">
        <div className="card"><h3 style={{fontSize:16,fontWeight:700,marginBottom:8}}>Authentication</h3><p style={{color:"var(--t2)",fontSize:13,lineHeight:1.6}}>API keys are issued per Studio account. All requests require Bearer token authentication. Rate limited to 1,000 requests/minute.</p></div>
        <div className="card"><h3 style={{fontSize:16,fontWeight:700,marginBottom:8}}>Webhooks</h3><p style={{color:"var(--t2)",fontSize:13,lineHeight:1.6}}>Real-time notifications for new submissions, callback decisions, and casting status changes.</p></div>
      </div>
      <div style={{textAlign:"center"}}><p style={{color:"var(--t2)",fontSize:14,marginBottom:16}}>API access is available with Studio enterprise plans</p><div style={{display:"flex",gap:12,justifyContent:"center"}}><button className="btn-p" onClick={()=>onNavigate("register-cd")}>Get Started</button><button className="btn-s" onClick={()=>onNavigate("contact")}>Contact Sales</button></div></div>
    </div>
    <Footer onNavigate={onNavigate}/></div>);
}

