  const LS_ETH_COUNTS="cs_acg_eth_counts_v1";
  const LS_TYPE_COUNTS="cs_acg_type_counts_v1";
  function countMap(k){
    try{const v=JSON.parse(localStorage.getItem(k)||"{}");return (v&&typeof v==="object"&&!Array.isArray(v))?v:{};}
    catch(_){return{};}
  }
