  // sentence-initial subject pronouns, and explicit "a man / a woman" nouns.
  const SKETCH_F=/(?:^|[.;—]\s+)(?:She|Her)\b|\b(?:a|the|this|one) (?:woman|girl|mother|daughter|sister|wife|widow)\b/;
