  function v3StoryWords(syn){return new Set(clean(v3Sentences(syn).filter(x=>!V7_PRACTICAL_RE.test(x)).slice(0,2).join(" ")).split(" ").filter(w=>w.length>4&&!V3_STORY_STOP.test(w)));}
