      byRank("Day Player").forEach(r=>{if(amt(r)>=leadMin&&isFinite(leadMin))r.pay=String(r.pay).replace(/\$[\d,]+/,()=>money(Math.max(25,r8Nice(leadMin*0.75))));});
      const minB=V6_MIN_BUDGET[type];
      const top=Math.max(...priced.map(amt));
