      "Documentary":()=>pick(["feature documentary","documentary feature"]),"Reality / Docu-Series":()=>`${eps}-episode docu-series`,"Lifestyle / Unscripted":()=>`${eps}-episode unscripted series`,"Hosting / Presenter":()=>`hosted ${pick(["web","online"])} series`
