      for(let i=slots.length-1;i>=0;i--)if(/\b(same person|same character|older self|younger self|as an adult|grown up|older version|younger version)\b/i.test(slots[i].s))slots.splice(i,1);
      const seenJob={};
      for(let i=slots.length-1;i>=0;i--)slots[i]._order=i;
      const slotsOk=slots.filter(s=>!(V4_POLICE.test(s.s)&&!policeOk)).filter(s=>{const k=v4FuncKey(s.s);if(!k)return true;const lab=String(s.s).toLowerCase();if(seenJob[k]&&!V4_QUAL.test(lab+" "+seenJob[k]))return false;seenJob[k]=lab;return true;}).map(s=>{
        const x=v3Sentences(s.x).filter(z=>!v4UnsetRefs(z,hayStems).length&&!v4ItWithoutObject(z,storyHay)&&!(V4_POLICE.test(z)&&!policeOk)&&!V4_FILLER.test(z)).join(" ");
        return {...s,x};
      }).filter(s=>s.x);
      slots.length=0;slotsOk.forEach(z=>slots.push(z));
      if(!slots.length){why('no slots');continue;}
      // "…asks him to end the search": the story fixes the lead's gender.
      const storyTxt=` ${seed.p} ${turn} `;
      const heS=/\b(he|him|his|himself)\b/i.test(storyTxt),sheS=/\b(she|her|hers|herself)\b/i.test(storyTxt);
      const lead0=slots.find(z=>z.r==="Lead");
      if(lead0&&!lead0.g&&heS!==sheS){const i=slots.indexOf(lead0);slots[i]={...lead0,g:heS?"M":"F"};}
      // A men's (or women's) campaign casts men (or women) in the parts the
      // product is for; staff parts stay open.
      const forWho=/\bmen's\b/i.test(`${seed.cat||""} ${seed.about||""}`)?"M":/\bwomen's\b/i.test(`${seed.cat||""} ${seed.about||""}`)?"F":"";
      if(forWho)slots.forEach((z,i)=>{if(!z.g&&!/\b(barber|staff|apprentice|clerk|associate|attendant|doctor|nurse|host)\b/i.test(z.s))slots[i]={...z,g:forWho};});
      // Round 3: pay tier, shoot plan, cast size, synopsis length and
      // schedule-note detail are each drawn against the board-wide mix.
      // Brand work names its category. When the seed has no mapped category,
      // it is read off the business the seed is set in (a laundromat, a
      // barbershop) — still a real category, never "a brand".
      const venueCat=()=>{const vs=(seed.w||[]).map(v3VenuePhrase).filter(Boolean);for(const v of vs){const hd=v5Head(v);if(hd&&hd.length>3&&!/^(room|floor|street|corner|table|window|counter|office|building|apartment|house|home|lot|site|area|yard|block)$/.test(hd))return hd.replace(/s$/,"");}return "";};
      const brandCat=V7_BRAND.test(type)?(seed.cat||adCategory(seed)||venueCat()||""):"";
      if(V7_BRAND.test(type)&&!brandCat){why('no product category');continue;}
      const plan=v5Plan(type,fam);
      // Round 8: the headline band is drawn first; the tier follows from it.
      const tiers8=v5PayTiers(type,plan.days);
      const band8=R8_ON?v5Pick(R8_PAY_MIX,v5Counts(h,res,"r8pay",R8_PAY_MIX),r8Bands(type,fam,tiers8,plan.days)):null;
      const payTier=(band8&&r8TierFor(band8,tiers8,type))||v5Pick(V5_PAY_MIX,v5Counts(h,res,"pay",V5_PAY_MIX),tiers8);
      const union=payTier==="union"?v5UnionFor(type)
        :fam==="stage"&&payTier==="deferred"&&type!=="Table Read"&&Math.random()<0.5?"AEA Showcase Code"
        :type==="Student Film"&&payTier==="deferred"&&Math.random()<0.4?"SAG-AFTRA Student Film":"Non-Union";
      if(!union){why('no union agreement');continue;}
      let noteTier=v5Pick(V5_NOTE_MIX,v5Counts(h,res,"note",V5_NOTE_MIX),["minimal","some","full"]);
      if(plan.mode==="flex1"&&noteTier==="minimal")noteTier="some";
      // Rehearsal days count for the leads only when the note says so.
