        castBucket=v5Pick(V5_CAST_MIX,v5Counts(h,res,"cast",V5_CAST_MIX),cp.allowed);
        const lo={"1":1,"2":2,"3-4":3,"5-7":5,"8+":8}[castBucket],hi={"1":1,"2":2,"3-4":4,"5-7":7,"8+":10}[castBucket];
