        if(era.length&&place.length&&chars.length&&Math.random()<0.5)worldUse.push({text:`${era[0].text.replace(/\.$/,"")}, and ${v5LowerFirst(place[0].text)}`,kind:"era"});
        else worldUse=worldUse.concat(era,place);
