  const ETH_KEYS=Object.keys(NAME_BANKS);
  // Given names that read as unisex within their own bank — used first when a
  // role is written non-binary, so the name does not fight the breakdown.
  const UNISEX_HINT=/^(Alex|Amal|Amari|Angel|Ari|Avery|Blake|Cameron|Casey|Dakota|Dallas|Devon|Ellis|Grace|Iman|Jaya|Jamie|Jesse|Jin|Jordan|Joy|Jun|Kai|Kalani|Kanoa|Keala|Kelly|Kiran|Lani|Leen|Logan|Makana|Manu|Marion|Max|Micah|Min|Moana|Morgan|Nikita|Noor|Nour|Omari|Perry|Pua|Quinn|Reese|Rian|Riley|Robin|Rowan|Sage|Sam|Sana|Shay|Simone|Tala|Taylor|Wei|Yara|Zain|Zara|Zion)$/i;
  // Ethnicity strings do not only arrive as the site's own option values —
  // hand-written legacy concepts use "Latina", "Black", "Caucasian", and a role
  // whose label the bank lookup misses would silently fall through to a random
  // heritage. That is exactly how a Latina role ends up called Yuki Tanaka.
  // Everything is normalised to a bank key first, and anything genuinely open
  // returns null on purpose.
  const ETH_ALIASES=[
    [/black|african[- ]?american|african descent|afro/i,"Black / African descent"],
    [/white|caucasian|european descent|eastern european|mediterranean/i,"White / European descent"],
    [/hispanic|latin[oax]|latina/i,"Hispanic / Latino"],
    [/south[- ]asian|indian|desi|pakistan|bangladesh|sri lank/i,"South Asian"],
    [/middle eastern|north african|arab|persian|mena/i,"Middle Eastern / North African"],
    [/native american|indigenous|american indian|first nations|alaska native/i,"Native American / Indigenous"],
    [/pacific islander|native hawaiian|polynesian|samoan|tongan/i,"Pacific Islander"],
    [/asian/i,"Asian"]
  ];
  function bankKeyFor(eth){
    const key=String(eth||"").trim();
    if(!key)return null;
    if(NAME_BANKS[key])return key;
    if(/^any\b|open to all|all ethnic|mixed|multiracial|biracial/i.test(key))return null;
    for(const [re,k] of ETH_ALIASES){if(re.test(key))return k;}
    return null;
  }
  function bankFor(eth){
    const k=bankKeyFor(eth);
    return k?NAME_BANKS[k]:null;
  }
  // Open roles and mixed-heritage roles both need to reach across banks — the
  // first pulls from everywhere so open casting isn't silently one-note, the
  // second pairs a given name from one heritage with a surname from another.
  function namePools(eth,gender){
    const g=gender==="Female"?"f":gender==="Male"?"m":null;
    const direct=bankFor(eth);
    // A non-binary role handed "Armando" or "Josephine" reads as a mistake, not
    // as range. Concatenating the unisex names in FRONT of the full list did not
    // help — a random pick over the joined array still lands on a gendered name
    // nine times in ten. So when the bank has a real unisex set, that IS the
    // pool; the full list is only the fallback for banks that do not.
    const take=(b)=>{
      if(g)return b[g];
      const uni=b.f.concat(b.m).filter(n=>UNISEX_HINT.test(n));
      return uni.length>=4?uni:b.f.concat(b.m);
    };
    if(direct)return{first:take(direct),last:direct.l,key:bankKeyFor(eth)};
    if(/mixed/i.test(eth||"")){
      const a=NAME_BANKS[pick(ETH_KEYS)],bk=pick(ETH_KEYS),b=NAME_BANKS[bk];
      return{first:take(a),last:b.l,key:bk};
    }
    // An OPEN role still needs an internally coherent name. Merging every bank
    // produced "Kenji Sheridan" and "Mahmoud Okada" — names that fight
    // themselves. So one heritage is chosen at random per name and both halves
    // come from it; variety happens across the board, not inside one name.
    const ok=pick(ETH_KEYS),one=NAME_BANKS[ok];
    return{first:take(one),last:one.l,key:ok};
  }
  function roleName(r,h,res){
    // A name the summary already used. It was minted through this same
    // function (so it is unique and matches the role's gender and ethnicity)
    // before the copy was written, because a summary that opens on a character
    // has to open on the character the breakdown actually casts.
    if(r._forceName)return r._forceName;
    // Group/atmosphere slots describe a crowd, not a person — they keep their
    // descriptive label ("Block Party Crowd") rather than being handed a
    // character name, and are still deduped so two listings never share one.
    if(r._group){
      // A group is a descriptive label, never a vague one: no "(Featured)",
      // "Crowd", "Stand-in" or "Group A" (v3).
      const rawBase=String(r._groupName||r.name||"Background");
      // A background label must name people: "Shop" becomes "People at the Shop".
      const peopleWord=V3_PEOPLE_WORD||/\b(people|customers|regulars|neighbors|passersby|patrons|guests|shoppers|riders|students|kids|children|crowd|audience|onlookers|workers|staff|crew|team|class|family|families|dancers|players|gardeners|volunteers|traders|members|visitors|diners|commuters|passengers|voices|ensemble|group|atmosphere|double|model|hands|lead|friends|coworkers|parents|fans|runners|swimmers|drivers|band|choir|chorus|congregation|tenants|mourners|guards|officers|nurses|patients|travelers|spectators|bidders|campers|members)\b/i;
      const base0=r._job||!/background/i.test(r.role_type||"")||peopleWord.test(rawBase)||/\b(queue|line|rush|performer|driver|double|voices?)\b/i.test(rawBase)?rawBase:`People at the ${titleCase(stripArticle(rawBase))}`;
      const base=base0.replace(/\bFeatured\b/g,"Principal").replace(/\bCrowd\b/g,"Onlookers").replace(/\bStand-?[Ii]n\b/g,"Lighting Double");
      return r._job||/background/i.test(base)||!/background/i.test(r.role_type||"")?base:`${base} (Background)`;
    }
    // v4: every person — character or crew — gets a familiar U.S. name from
    // v4PickName, which never reuses a full name, respects the 50-project
    // cooldown and returns nothing rather than a reused or unfamiliar name.
    return v4PickName(r,h,res)||"";
  }

  function varyRoleDescription(r,original,voice,charName){
    const base=String(r.description||"").trim();
    // Seed slots arrive as finished character sketches — passing them through
    // sent(base,1) would lop off the half that says how to play it. They are
    // framed here instead, because this is the first point at which the
    // character's real name exists.
    if(r._full)return frameSeedDescription({...r,description:base},charName);
    if(r._job||r._rawDesc)return base;
    if(r._keepDescription)return sent(base,1)||base;
    // A lead described in four words tells an actor nothing. Bigger parts draw
    // from the longer end of the scale; only the small parts can come out tiny.
    const big=/lead|principal|supporting|series regular|recurring/i.test(r.role_type||"");
    const len=pick(big?["medium","long","long","medium","short"]:ROLE_LENGTHS);
    const first=sent(base,1);
    const second=sent(base,2);
    const color=pick([
      "Specific relationship to the other characters matters more than resume size.",
      "A lived-in read will beat a theatrical one here.",
      "Should feel like a person with a day before and after this scene.",
      "The role has room for humor if it stays grounded.",
      "Strong listening is more important than a perfect line read.",
      "Please avoid making the character a type; the casting team wants detail."
    ]);
    if(len==="tiny")return first||base;
    if(len==="short")return second||base;
    if(len==="medium")return `${base} ${voice.role}`;
    return `${base} ${color} ${voice.role}`;
  }
  function rolePay(type,roleType){
    const rt=clean(roleType);
    if(rt.includes("background"))return pick(["$100-$150/day","$125/day","$150/day"]);
    if(rt.includes("stand"))return pick(["$125-$200/day","$150/day","$175/day"]);
    if(/theater|musical|stage|table read|broadway/i.test(type)){
      if(/lead|principal/i.test(roleType))return pick(["$400-$800 total","$500 total","Workshop stipend"]);
      return pick(["$200-$450 total","$250 total","Workshop stipend"]);
    }
    if(/student/i.test(type)){
      if(/lead|principal/i.test(roleType))return pick(["$100-$225/day","$125/day","$150/day"]);
      return pick(["$50-$150/day","$75/day","$100/day"]);
    }
    if(/tv|series|pilot|streaming|web series/i.test(type)){
      if(/lead|principal/i.test(roleType))return pick(["$300-$750/day","$450/day","$600/day"]);
      return pick(["$175-$350/day","$225/day","$300/day"]);
    }
    if(/feature|independent film/i.test(type)){
      if(/lead|principal/i.test(roleType))return pick(["$300-$625/day","$350/day","$500/day"]);
      return pick(["$175-$275/day","$200/day","$250/day"]);
    }
    if(/short film|experimental film|documentary|proof|sizzle|pitch/i.test(type)){
      if(/lead|principal/i.test(roleType))return pick(["$150-$325/day","$200/day","$275/day"]);
      return pick(["$100-$175/day","$125/day","$150/day"]);
    }
    if(/commercial|ad|brand/i.test(type))return pick(["$400-$750/day","$500/day plus a payment for how long the ad runs","$300-$600/day","$1,000 flat","$150-$300/day"]);
    return pick(["$125-$250/day","$150-$300/day","$75-$175/day"]);
  }
  function extraRolesFor(type){
    const extras=[];
    if(Math.random()<0.48)extras.push({...pick(BACKGROUND_ROLE_BANK)});
    if(Math.random()<0.24)extras.push({...pick(STANDIN_ROLE_BANK)});
    if(type==="Commercials & Branded Content"&&Math.random()<0.28)extras.push({...pick(BACKGROUND_ROLE_BANK)});
    return extras.slice(0,pick([1,1,2]));
  }
  // ── Breakdown conventions ────────────────────────────────────────────────
  // Learned from the structure of professional breakdowns (format only — the
  // ones on Breakdown Services carry an explicit confidentiality notice and
  // none of their text is used here). Three things they do that we did not:
  //   • role descriptions name the OTHER characters in the same breakdown, so
  //     a cast reads as one story rather than five separate adverts;
  //   • child and teen roles state a playing age separately from the band the
  //     production will read — "to play 15" against a 13-19 band;
  //   • any breakdown containing a minor carries a child-performer compliance
  //     note, every time, without exception.
  const PLAY_AGE={child:[7,8,9,10,11],teen:[13,14,15,16,17],youngAdult:[19,20,21,22,24]};
  function midOfBand(band){
    const m=String(band||"").match(/(\d+)\s*-\s*(\d+)/);
    if(!m)return null;
    const lo=+m[1],hi=+m[2];
    return Math.round(lo+(hi-lo)*(0.3+Math.random()*0.3));
  }
  // "Shares the bulk of the film with Zoya" on an Off-Broadway musical is the
  // kind of slip that tells a reader nobody looked at this. The scene-partner
  // line takes the medium from the project type.
  function mediumNoun(type){
    const t=String(type||"");
    if(/live event|hosting|performance art/i.test(t))return "show";
    if(/music video/i.test(t))return "video";
    if(/dance project|motion capture/i.test(t))return "piece";
    if(/reality|lifestyle/i.test(t))return "series";
    if(/theater|theatre|musical|staged reading|workshop|table read/i.test(t))return "play";
    if(/print campaign|photo shoot|modeling/i.test(t))return "campaign";
    if(/commercial|branded|social media ad|promo|product demo|ad campaign|public service/i.test(t))return "spot";
    if(/voiceover|podcast|audio drama|animation|video game/i.test(t))return "series";
    if(/tv|series|pilot|miniseries/i.test(t))return "episode";
    return "film";
  }
  function boardPolish(roles,h,res,type){
    const medium=mediumNoun(type);
    const named=roles.filter(r=>!r._group);
    const leads=named.filter(r=>/lead|principal/i.test(r.role_type||""));
    const usedPartners=new Set();
    return roles.map((r,i)=>{
      if(r._group)return r;
      let d=String(r.description||"").trim();
      // Playing age, stated the way a breakdown states it.
      const lo=parseInt(String(r.age_range||"").split("-")[0],10);
      // Round 3: no "To play N." tacked on — the age range already says it.
      // Name a scene partner. Only ever states who they play against, which is
      // true by construction — it never invents a family relationship.
      const others=named.filter(o=>o!==r).map(o=>o.name);
      // v4: no invented scene-partner lines ("Every scene they have is
      // against X") — who works with whom must come from the story.
      if(false&&others.length){
        // v3: each partner is named once per listing, so two roles never carry
        // the same line about the same person.
        const partnerPool=(leads.length&&!leads.includes(r)?leads.map(o=>o.name).filter(n=>n!==r.name):others).filter(n=>!usedPartners.has(n));
        const partner=partnerPool.length?pick(partnerPool):null;
        if(partner){
          usedPartners.add(partner);
          const second=pick(others.filter(n=>n!==partner));
          d+=" "+pick([
            `Most of their scenes are with ${partner}.`,
            `Plays opposite ${partner}.`,
            `Shares the bulk of the ${medium} with ${partner}.`,
            second?`Scenes with ${partner} and ${second}.`:`Plays opposite ${partner}.`,
            `Every scene they have is against ${partner}.`,
            `Most of their scenes are opposite ${partner}.`
          ]);
        }
      }
      if(res)res.lines.add(clean(d));
      return{...r,description:d};
    });
  }
  // Some formats need something a headshot and a self-tape cannot show. A
  // musical that never asks for a song, or a dance film that never asks to see
  // you move, reads as a listing written by someone who has not done this.
  function craftNote(type){
    const t=String(type||"");
    if(/musical/i.test(t))return " "+pick([
      "Please include 32 bars of a contemporary musical theatre song — unaccompanied or to a track is equally fine.",
      "Add a short sung cut with your submission: one song, 60 seconds, anything that sits in your voice.",
      "We need to hear you sing. A phone recording of one song is plenty at this stage."
    ]);
    if(/dance|performance art/i.test(t))return " "+pick([
      "Please add a short movement clip — a class, a rehearsal, or 30 seconds of your own choreography.",
      "Include any footage of you moving. It does not have to be polished or recent.",
      "A movement reel matters more than a scene here. One minute is enough."
    ]);
    if(/motion capture|video game/i.test(t))return " "+pick([
      "If you have any movement, stunt or physical theatre background, say so in your note.",
      "Tell us about any capture, stunt or movement work you have done — none is fine too."
    ]);
    return "";
  }
  // Every breakdown with a minor in it says so, in the same place, every time.
  function minorsNote(roles){
    const hasMinor=(roles||[]).some(r=>{
      const lo=parseInt(String(r.age_range||"").split("-")[0],10);
      return isFinite(lo)&&lo<18;
    });
    if(!hasMinor)return "";
    return " ROLES FOR MINORS: a parent or guardian must be present and within sight and sound at all times. No mature content. This production works to the applicable state child performer laws, and permits are the production's responsibility.";
  }
  function uniqueRoles(baseRoles,h,res,type,voice,allowExtras=true){
    const withExtras=[...(baseRoles||[]),...(allowExtras?extraRolesFor(type):[])];
    const built=withExtras.map(r=>{
      const original=r.name;
      const name=roleName(r,h,res);
      const roleType=r.role_type||inferRoleType(original,r.description);
      return{...r,name,description:varyRoleDescription(r,original,voice,name),role_type:roleType,pay:r.pay||rolePay(type,roleType)};
    });
    return boardPolish(built,h,res,type);
  }

